<?php if($canFinance): ?><?php if((float)gh_lc_v($checkout,'refundable_amount',0)>(float)gh_lc_v($checkout,'paid_amount',0)): ?><details open><summary>Catat pembayaran refund</summary><p class="muted">Hanya isi setelah transfer nyata dilakukan. Bukti transfer wajib dilampirkan. Jangan mencatat kewajiban refund sebagai pembayaran.</p><form method="post" action="<?= $actionUrl; ?>" enctype="multipart/form-data" data-lc-form data-confirm="Catat transfer refund yang benar-benar sudah dilakukan beserta bukti ini?"><input type="hidden" name="action" value="refund"><div class="lc-fields"><label>Nominal yang ditransfer (Rp)<input type="number" name="amount" min="1" step="1" required></label><label>Tanggal transfer aktual<input type="date" name="transfer_date" value="<?= date('Y-m-d'); ?>" max="<?= date('Y-m-d'); ?>" required></label><label>Nomor referensi transfer<input name="reference_no" maxlength="150" required></label><label>Bukti transfer *<input type="file" name="proof_file" accept=".pdf,.jpg,.jpeg,.png" required><span class="lc-help">PDF/JPG/PNG maksimal 10 MB.</span></label></div><button type="submit">Catat transfer pengembalian deposit</button></form></details><?php elseif((float)gh_lc_v($checkout,'disputed_amount',0)===0.0): ?><div class="lc-alert success" role="status">Pengembalian deposit telah selesai. Tidak ada sisa pembayaran refund.</div><?php else: ?><div class="lc-alert">Bagian deposit yang tidak diperselisihkan sudah diselesaikan. Selesaikan klarifikasi untuk menetapkan sisa pengembalian.</div><?php endif; ?><?php if((float)gh_lc_v($checkout,'disputed_amount',0)>0): ?><details><summary>Selesaikan klarifikasi potongan</summary><form method="post" action="<?= $actionUrl; ?>" data-lc-form data-confirm="Simpan keputusan klarifikasi dan ubah nominal deposit yang dapat dikembalikan?"><input type="hidden" name="action" value="resolve_dispute"><div class="lc-fields"><label>Nominal yang dilepas untuk penghuni (Rp)<input type="number" name="released_amount" min="0" max="<?= (float)$checkout['disputed_amount']; ?>" required></label><label>Hasil kesepakatan dan referensi bukti<textarea name="resolution_note" required maxlength="5000"></textarea></label></div><button type="submit">Simpan penyelesaian klarifikasi</button></form></details><?php endif; ?><?php endif; ?>
<h3 style="margin-top:24px">Riwayat transfer refund</h3><div class="lc-table-wrap"><table><thead><tr><th>Tanggal</th><th>Nominal</th><th>Referensi</th><th>Bukti</th></tr></thead><tbody><?php foreach($refunds as $refund): ?><tr><td><?= gh_lc_e(gh_lc_v($refund,'transfer_date')); ?></td><td><?= gh_lc_money(gh_lc_v($refund,'amount',0)); ?></td><td><?= gh_lc_e(gh_lc_v($refund,'reference_no')); ?></td><td><?php if(!empty($refund['proof_file_id'])): ?><a href="<?= base_url('lifecycle/file/'.(int)$refund['proof_file_id']); ?>" target="_blank" rel="noopener">Lihat bukti transfer</a><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$refunds): ?><tr><td colspan="4" class="lc-empty">Belum ada transfer refund yang dicatat.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?></section>